# WGCNA on pseudo-bulk samples built from Zeisel cortex/hippocampus cells (7 cell types x 10 random pseudo-replicates)
suppressPackageStartupMessages({library(WGCNA); library(Seurat); library(Matrix)}); allowWGCNAThreads(4)
setwd(dirname(sub("--file=","",grep("--file=",commandArgs(FALSE),value=TRUE))))
so <- readRDS("../_data/zeisel_seurat.rds"); set.seed(1)
grp <- paste(so$celltype, sample(1:10, ncol(so), replace = TRUE), sep = "_")
cnt <- GetAssayData(so, layer = "counts"); pb <- sapply(split(colnames(so), grp), function(cc) Matrix::rowSums(cnt[, cc, drop = FALSE]))
lcpm <- log2(t(t(pb)/colSums(pb))*1e6 + 1); keep <- head(order(-apply(lcpm, 1, var)), 3000); datExpr <- t(lcpm[keep,])
sft <- pickSoftThreshold(datExpr, powerVector = c(1:10, seq(12,20,2)), networkType = "signed", verbose = 0)
png("v1_soft_threshold.png", 1400, 650, res = 150); par(mfrow = c(1,2)); fi <- sft$fitIndices
plot(fi[,1], -sign(fi[,3])*fi[,2], type = "n", xlab = "Soft threshold (power)", ylab = "Scale-free fit, signed R^2", main = "Scale independence"); text(fi[,1], -sign(fi[,3])*fi[,2], fi[,1], col = "red"); abline(h = .8, col = "red")
plot(fi[,1], fi[,5], type = "n", xlab = "Soft threshold (power)", ylab = "Mean connectivity", main = "Mean connectivity"); text(fi[,1], fi[,5], fi[,1], col = "red"); dev.off()
pw <- ifelse(is.na(sft$powerEstimate), 12, sft$powerEstimate)
net <- blockwiseModules(datExpr, power = pw, networkType = "signed", TOMType = "signed", minModuleSize = 30, mergeCutHeight = .25, numericLabels = FALSE, verbose = 0, maxBlockSize = 5000)
png("v2_dendro_modules.png", 1400, 800, res = 150); plotDendroAndColors(net$dendrograms[[1]], net$colors[net$blockGenes[[1]]], "Module", dendroLabels = FALSE, hang = .03, addGuide = TRUE, guideHang = .05, main = "Gene dendrogram and module colours"); dev.off()
ct <- sub("_[0-9]+$", "", rownames(datExpr)); traits <- sapply(unique(ct), function(x) as.numeric(ct == x)); rownames(traits) <- rownames(datExpr)
ME <- orderMEs(net$MEs); mt <- cor(ME, traits); mp <- corPvalueStudent(mt, nrow(datExpr))
png("v3_module_trait.png", 1300, 1300, res = 150); par(mar = c(9,9,3,3))
labeledHeatmap(mt, xLabels = colnames(traits), yLabels = names(ME), ySymbols = names(ME), colorLabels = FALSE, colors = blueWhiteRed(50), textMatrix = paste0(signif(mt,2), "\n(", signif(mp,1), ")"), setStdMargins = FALSE, cex.text = .5, zlim = c(-1,1), main = "Module-cell type relationships"); dev.off()
png("v4_eigengene_network.png", 1100, 1300, res = 150); plotEigengeneNetworks(ME, "Eigengene dendrogram and adjacency", marDendro = c(0,4,2,0), marHeatmap = c(3,4,2,2), xLabelsAngle = 90); dev.off()
